#if UNITY_EDITOR
using System;
using System.IO;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using LastRail.Battle;
using LastRail.Run;
namespace LastRail.Tests.EditMode {
 public sealed class BRuntimeObservationDeliveryTests {
  const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BRuntimeObservationDelivery-20261006/";
  static JObject Finished()=>JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BNativeTwoWave-20261005/two-wave-http-result.json"));
  static BRouteRuntimeObservation Extract(JObject root){var r=(JObject)root["route"];var binding=BRouteBinding.Read(r.ToString(),(string)r["packetHash"],(string)r["accountId"],(string)r["runId"]);try{return (BRouteRuntimeObservation)Activator.CreateInstance(typeof(BRouteRuntimeObservation),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{binding,(JObject)root["nodeSession"]},null);}catch(TargetInvocationException e){throw e.InnerException;}}
  static BRouteRuntimeObservation Final()=>Extract((JObject)Finished()["controller"]);
  [Test] public void OriginalControllerRequiresImmutableExtractionAndOwnedDeliveryBoundary(){Assert.NotNull(typeof(BRouteSessionController).GetMethod("CaptureOriginalRuntimeObservation"));Assert.NotNull(typeof(BRouteSessionController).GetMethod("ForwardOriginalRuntimeObservationAsync"));}
  [Test] public void ExistingCompletedEvidenceExtractsExactRawEventsWithoutInventingArrival(){var original=Final();Assert.AreEqual(507,original.SourceRevision);Assert.AreEqual("resume-step-362",original.OriginalCommandEventId);Assert.AreEqual(14435,(long)original.OriginalClock["completedSteps"]);Assert.AreEqual(622,(long)original.OriginalWaveClearEvents[0]["sequence"]);Assert.AreEqual(8060,(long)original.OriginalWaveClearEvents[0]["tick"]);Assert.AreEqual(1048,(long)original.OriginalWaveClearEvents[1]["sequence"]);Assert.IsNull(original.OriginalWaveClearEvents[0]["eventId"]);Assert.AreEqual("TRAVELLING",(string)original.OriginalRoute["phase"]);Assert.Throws<InvalidOperationException>(()=>original.RequireTravelArrival());Assert.IsFalse((bool)original.OriginalNodeSession["observation"]["canPrepareTrustedMaintenance"]);var hash=original.CheckpointHash;var copy=original.OriginalCheckpoint;copy["sequence"]=1;var events=original.OriginalWaveClearEvents;events[0]["tick"]=1;Assert.AreEqual(hash,original.CheckpointHash);Assert.AreEqual(8060,(long)original.OriginalWaveClearEvents[0]["tick"]);File.WriteAllText(Qa+"original-extraction.json",new JObject{["originalRoute"]=original.OriginalRoute,["originalNodeSession"]=original.OriginalNodeSession}.ToString());}
  [TestCase("runtime")][TestCase("hazards")][TestCase("node")]
  public void MixedOwnerCapturesAreRejected(string part){var root=(JObject)Finished()["controller"].DeepClone();if(part=="runtime")root["nodeSession"]["runtime"]["sequence"]=1;else if(part=="hazards")root["nodeSession"]["observation"]["hazards"]["tick"]=1;else root["nodeSession"]["node"]["nativeContextId"]="foreign";Assert.Throws<ArgumentException>(()=>Extract(root));}
  [Test] public async Task LocalForwardAndCursorRestoreSuppressDuplicateWithoutServerReceipt(){var o=Final();int calls=0;using(var delivery=new BRuntimeObservationDelivery(()=>o)){Func<BRouteRuntimeObservation,CancellationToken,Task> send=(x,t)=>{calls++;Assert.AreEqual(o.DeliveryKey,x.DeliveryKey);return Task.CompletedTask;};Assert.AreEqual(BLocalObservationDeliveryStatus.Forwarded,await delivery.ForwardAsync(o,send));Assert.AreEqual(BLocalObservationDeliveryStatus.AlreadyForwarded,await delivery.ForwardAsync(o,send));var cursor=delivery.CaptureCursor();using(var restored=new BRuntimeObservationDelivery(()=>o)){restored.RestoreCursor(cursor,BDirectAttackInput.Digest(cursor));Assert.AreEqual(BLocalObservationDeliveryStatus.AlreadyForwarded,await restored.ForwardAsync(o,send));}Assert.AreEqual(1,calls);Assert.IsNull(cursor["accepted"]);}}
  [Test] public async Task ConcurrentDuplicateCallsOriginalCallbackOnce(){var o=Final();int calls=0;var gate=new TaskCompletionSource<bool>();using(var d=new BRuntimeObservationDelivery(()=>o)){var task=d.ForwardAsync(o,(x,t)=>{calls++;return gate.Task;});Assert.AreEqual(BLocalObservationDeliveryStatus.AlreadyInFlight,await d.ForwardAsync(o,(x,t)=>{calls++;return Task.CompletedTask;}));gate.SetResult(true);Assert.AreEqual(BLocalObservationDeliveryStatus.Forwarded,await task);Assert.AreEqual(1,calls);}}
  [Test] public async Task CallbackFailurePreservesCursorAndAllowsExactRetry(){var o=Final();using(var d=new BRuntimeObservationDelivery(()=>o)){var before=d.CaptureCursor();Assert.ThrowsAsync<InvalidOperationException>(async()=>await d.ForwardAsync(o,(x,t)=>Task.FromException(new InvalidOperationException("original-forward-failed"))));Assert.IsTrue(JToken.DeepEquals(before,d.CaptureCursor()));Assert.AreEqual(BLocalObservationDeliveryStatus.Forwarded,await d.ForwardAsync(o,(x,t)=>Task.CompletedTask));}}
  [Test] public async Task CancelledCallerDoesNotMarkLocalDeliveryComplete(){var o=Final();using(var d=new BRuntimeObservationDelivery(()=>o))using(var caller=new CancellationTokenSource()){var task=d.ForwardAsync(o,(x,t)=>Task.Delay(10000,t),caller.Token);caller.Cancel();try{await task;Assert.Fail("Cancellation must propagate");}catch(OperationCanceledException){}Assert.IsFalse((bool)d.CaptureCursor()["locallyForwarded"]);}}
  [Test] public async Task InvalidatedBorrowedCallbackCannotPublishLateOrDisposeSource(){var o=Final();var gate=new TaskCompletionSource<bool>();using(var d=new BRuntimeObservationDelivery(()=>o)){CancellationToken token=default;var task=d.ForwardAsync(o,(x,t)=>{token=t;return gate.Task;});d.Invalidate();Assert.IsTrue(token.IsCancellationRequested);gate.SetResult(true);Assert.AreEqual(BLocalObservationDeliveryStatus.Superseded,await task);Assert.IsFalse((bool)d.CaptureCursor()["locallyForwarded"]);Assert.AreEqual(14435,(long)o.OriginalClock["completedSteps"]);}}
  [Test] public void CursorCannotBeTransferredToDifferentOriginalDelivery(){var o=Final();using(var d=new BRuntimeObservationDelivery(()=>o)){var cursor=d.CaptureCursor();cursor["originalDeliveryKey"]="sha256:foreign";Assert.Throws<ArgumentException>(()=>d.RestoreCursor(cursor,BDirectAttackInput.Digest(cursor)));Assert.IsFalse((bool)d.CaptureCursor()["locallyForwarded"]);}}
  [TestCase(false)][TestCase(true)] public async Task ControllerUnbindOrDisposalCancelsOnlyOwnedDeliveryAndRejectsLateCompletion(bool dispose){using(var c=await ShortSession()){var original=c.CaptureOriginalRuntimeObservation();var gate=new TaskCompletionSource<bool>();CancellationToken token=default;var task=c.ForwardOriginalRuntimeObservationAsync(original,(x,t)=>{token=t;return gate.Task;});if(dispose)c.Dispose();else c.Unbind();Assert.IsTrue(token.IsCancellationRequested);gate.SetResult(true);Assert.AreEqual(BLocalObservationDeliveryStatus.Superseded,await task);Assert.AreEqual(1,original.SourceRevision);}}
  [Test] public async Task OriginalSourceCannotBeReplacedWhileCursorAssumesNewCheckpoint(){using(var c=await ShortSession()){var o=c.CaptureOriginalRuntimeObservation();var cursor=c.CaptureLocalDeliveryCursor();var before=c.Capture();c.Advance("short-next-checkpoint",100000,10);var current=c.Capture();Assert.Throws<ArgumentException>(()=>c.RestoreLocalDeliveryCursor(cursor,BDirectAttackInput.Digest(cursor)));Assert.IsTrue(JToken.DeepEquals(current,c.Capture()));Assert.ThrowsAsync<InvalidOperationException>(async()=>await c.ForwardOriginalRuntimeObservationAsync(o,(x,t)=>Task.CompletedTask));}}
  [Test] public async Task ThrowingCancellationHandlerCannotLeaveControllerAlive(){var c=await ShortSession();var o=c.CaptureOriginalRuntimeObservation();var gate=new TaskCompletionSource<bool>();CancellationTokenRegistration registration=default;var pending=c.ForwardOriginalRuntimeObservationAsync(o,(x,t)=>{registration=t.Register(()=>throw new InvalidOperationException("cancel-handler-failed"));return gate.Task;});try{Assert.Throws<AggregateException>(()=>c.Dispose());Assert.Throws<ObjectDisposedException>(()=>c.Capture());gate.SetResult(true);Assert.AreEqual(BLocalObservationDeliveryStatus.Superseded,await pending);}finally{registration.Dispose();c.Dispose();if(!gate.Task.IsCompleted)gate.SetResult(true);}}
  [Test] public async Task ThrowingViewCannotLeaveOldCheckpointDeliveryRunning(){using(var c=await ShortSession()){c.Bind(_=>throw new InvalidOperationException("view-failed"));var o=c.CaptureOriginalRuntimeObservation();var gate=new TaskCompletionSource<bool>();CancellationToken token=default;var pending=c.ForwardOriginalRuntimeObservationAsync(o,(x,t)=>{token=t;return gate.Task;});Assert.Throws<InvalidOperationException>(()=>c.Advance("new-checkpoint-view-error",100000,10));Assert.IsTrue(token.IsCancellationRequested,"Cancel previous source before invoking external View callback");gate.SetResult(true);Assert.AreEqual(BLocalObservationDeliveryStatus.Superseded,await pending);}}
  static async Task<BRouteSessionController> ShortSession(){var p=BNativeNodeSourceTests.First();var bundle=BNativeNodeSourceSnapshot.Read(p.ToString(),(string)p["packetHash"],"a","LOCAL_B12_RUN");var b=BRouteNativeTests.Binding(bundle.Boarding);var g=BOrdinaryGeometryTests.Geometry(b);var rail=global::CombatRailJourneyTests.Config();rail["offers"]=new JArray();rail["throttleMaximumBps"]=13000;rail["throttleCruiseBps"]=10000;var motion=BTravelRuntimeConfiguration.LocalValidation(rail,BDirectAttackInput.Digest(rail));var comp=new BRouteNativeComposition(bundle.Route,bundle.Boarding,b,g,motion,10000);var c=new BRouteSessionController("a","LOCAL_B12_RUN");await c.RefreshAsync(()=>Task.FromResult(bundle.Route));comp.AttachTo(c);c.Advance("short-original",100000,10);return c;}
  [Test] public async Task NewOriginalCommandCancelsPendingLocalObservationButRejectedCommandPreservesIt(){using(var c=await ShortSession()){var original=c.CaptureOriginalRuntimeObservation();var gate=new TaskCompletionSource<bool>();CancellationToken token=default;var pending=c.ForwardOriginalRuntimeObservationAsync(original,(x,t)=>{token=t;return gate.Task;});var before=c.Capture();Assert.Throws<ArgumentException>(()=>c.Advance("invalid-negative-time",-1,10));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));Assert.IsFalse(token.IsCancellationRequested);c.Advance("short-next",100000,10);Assert.IsTrue(token.IsCancellationRequested,"New accepted native checkpoint must cancel old forwarded observation");gate.SetResult(true);Assert.AreEqual(BLocalObservationDeliveryStatus.Superseded,await pending);}}
 }
}
#endif